--
-- Table structure for table `tbl_order_status`
--

DROP TABLE IF EXISTS `tbl_order_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_order_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `status_name` varchar(255) NOT NULL COMMENT 'Pending – Order placed but not yet processed.\r\n\r\nProcessing – Order is being prepared.\r\n\r\nAccepted – Order has been accepted and confirmed.\r\n\r\nPacked – Items have been packed and are ready for shipment.\r\n\r\nShipped – Order has been dispatched.\r\n\r\nIn Transit – Order is on the way to the delivery address.\r\n\r\nOut for Delivery – Courier is delivering the order.\r\n\r\nDelivered – Order successfully delivered.\r\n\r\nCancelled – Order was cancelled (by customer or admin).\r\n\r\nReturned – Customer returned the product.\r\n\r\nRefunded – Refund has been issued.\r\n\r\nFailed – Payment failed or order couldn’t be processed.',
  `status_color` varchar(255) DEFAULT NULL,
  `status_order_no` int(11) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  `is_deleted` int(11) NOT NULL DEFAULT '1',
  `create_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tbl_order_status`
--

LOCK TABLES `tbl_order_status` WRITE;
/*!40000 ALTER TABLE `tbl_order_status` DISABLE KEYS */;
